private fun onKeyEvent(event: KeyEvent) = catchExceptions {
    // AWT can send events after the window is disposed
    if (isDisposed) {
        return
    }
    if (eventListener.onKeyEvent(event)) {
        return
    }
    val composeEvent = event.toComposeEvent()
    textInputService.onKeyEvent(event)
    textInputService2.onKeyEvent(event)
    windowContext.setKeyboardModifiers(composeEvent.internal.modifiers)
    if (onPreviewKeyEvent(composeEvent) ||
        scene.sendKeyEvent(composeEvent) ||
        onKeyEvent(composeEvent) ||
        navigationEventInput.onKeyEvent(composeEvent)
    ) {
        event.consume()
    }
}

internal abstract class BaseComposeScene(
    coroutineContext: CoroutineContext,
    private val invalidate: () -> Unit,
) : ComposeScene {
    protected val snapshotInvalidationTracker = SnapshotInvalidationTracker(::updateInvalidations)
    protected val inputHandler: ComposeSceneInputHandler =
        ComposeSceneInputHandler(
            prepareForPointerInputEvent = ::doMeasureAndLayout,
            processPointerInputEvent = ::onPointerInputEvent,
            cancelPointerInput = ::processCancelPointerInput,
            processKeyEvent = ::processKeyEvent,
        )

    private val frameClock = BroadcastFrameClock(onNewAwaiters = ::updateInvalidations)
    private val recomposer: ComposeSceneRecomposer =
        ComposeSceneRecomposer(coroutineContext, frameClock)
    private var composition: Composition? = null

    protected val compositionContext: CompositionContext
        get() = recomposer.compositionContext

    abstract val composeSceneContext: ComposeSceneContext

    protected var isClosed = false
        private set

    private var isInvalidationDisabled = false
    private inline fun <T> postponeInvalidation(traceTag: String, crossinline block: () -> T): T = trace(traceTag) {
        check(!isClosed) { "postponeInvalidation called after ComposeScene is closed" }
        isInvalidationDisabled = true
        return try {
            // Try to get see the up-to-date state before running block
            // Note that this doesn't guarantee it, if sendApplyNotifications is called concurrently
            // in a different thread than this code.
            snapshotInvalidationTracker.sendAndPerformSnapshotChanges()
            snapshotInvalidationTracker.performSnapshotChangesSynchronously(block)
        } finally {
            snapshotInvalidationTracker.sendAndPerformSnapshotChanges()
            isInvalidationDisabled = false
        }.also {
            updateInvalidations()
        }
    }

override fun render(canvas: Canvas, nanoTime: Long) {
    // This is a no-op if the scene is closed, this situation can happen if the scene is
    // in the list for rendering, but recomposition in another scene from the same list
    // processed earlier has closed it.

    if (isClosed) return

    postponeInvalidation("BaseComposeScene:render") {
        // We try to run the phases here in the same order Android does.

        // Flush composition effects (e.g. LaunchedEffect, coroutines launched in
        // rememberCoroutineScope()) before everything else
        recomposer.performScheduledEffects()

        recomposer.performScheduledRecomposerTasks()
        frameClock.sendFrame(nanoTime) // withFrameMillis/Nanos and recomposition

        doMeasureAndLayout()  // Layout

        // Schedule synthetic events to be sent after `render` completes
        if (inputHandler.needUpdatePointerPosition) {
            recomposer.scheduleAsEffect {
                inputHandler.updatePointerPosition()
            }
        }

        // Between layout and draw, Android's Choreographer flushes the main dispatcher.
        // We can't do quite that, but an important side effect of that is that the
        // GlobalSnapshotManager gets to run and call `Snapshot.sendApplyNotifications()`, which
        // we can (and must) do.
        Snapshot.sendApplyNotifications()

        // The drawing phase.
        // Android calls these two before drawing (AndroidComposeView.dispatchDraw)
        doMeasureAndLayout()
        Snapshot.sendApplyNotifications()

        // Actually draw
        snapshotInvalidationTracker.onDraw()
        draw(canvas)
    }

override fun sendKeyEvent(keyEvent: KeyEvent): Boolean = postponeInvalidation("BaseComposeScene:sendKeyEvent") {
    inputHandler.onKeyEvent(keyEvent).also {
        recomposer.performScheduledEffects()
    }
}

internal class ComposeSceneRecomposer(
    coroutineContext: CoroutineContext,
    vararg elements: CoroutineContext.Element
) {
    private val job = Job()
    private val coroutineScope = CoroutineScope(coroutineContext + job)

    /**
     * We use [FlushCoroutineDispatcher] not only because we need [FlushCoroutineDispatcher.flush]
     * for LaunchEffect tasks, but also to know whether it is idle (has no scheduled tasks)
     */
    private val effectDispatcher = FlushCoroutineDispatcher(coroutineScope)
    private val recomposeDispatcher = FlushCoroutineDispatcher(coroutineScope)
    private val recomposer = Recomposer(coroutineContext + job + effectDispatcher)

    /**
     * `true` if there is any pending work scheduled, regardless of whether it is currently running.
     */
    val hasPendingWork: Boolean
        get() = recomposer.hasPendingWork ||
        effectDispatcher.hasImmediateTasks() ||
        recomposeDispatcher.hasImmediateTasks()

    val compositionContext: CompositionContext
        get() = recomposer

    init {
        var context: CoroutineContext = recomposeDispatcher
        for (element in elements) {
            context += element
        }
        coroutineScope.launch(context,
            start = CoroutineStart.UNDISPATCHED
        ) {
            recomposer.runRecomposeAndApplyChanges()
        }
    }

    /**
     * Perform all scheduled recomposer tasks and wait for the tasks which are already
     * performing in the recomposition scope.
     */
    fun performScheduledRecomposerTasks() =
        trace("ComposeSceneRecomposer:performScheduledRecomposerTasks") {
            recomposeDispatcher.flush()
        }

    /**
     * Perform all scheduled effects.
     */
    fun performScheduledEffects() = trace("ComposeSceneRecomposer:performScheduledEffects") {
        effectDispatcher.flush()
    }

internal class SnapshotInvalidationTracker(
    private val invalidate: () -> Unit = {}
) {
    private val snapshotChanges = CommandList(invalidate)
    private var needMeasureAndLayout = true
    private var needDraw = true

    /**
     * The id of the thread currently inside [performSnapshotChangesSynchronously].
     *
     * Note that it's not valid to have more than one thread calling it at the same time.
     */
    private var renderingThreadId: Long? by atomic(null)

    val hasInvalidations: Boolean
        get() = needMeasureAndLayout || needDraw || snapshotChanges.hasCommands

fun snapshotObserver() = OwnerSnapshotObserver { command ->
    if (renderingThreadId == getCurrentThreadId())
        command()
    else
        snapshotChanges.add(command)
}

/**
 * Sends any pending apply notifications and performs the changes they cause.
 */
fun sendAndPerformSnapshotChanges() {
    Snapshot.sendApplyNotifications()
    snapshotChanges.perform()
}

/**
 * Runs [block], performing any snapshot changes it generates synchronously.
 *
 * See [OwnerSnapshotObserverTest.observeReadsChangedBeforeDisposeEffect] for more details.
 */
inline fun <T> performSnapshotChangesSynchronously(block: () -> T): T {
    return try {
        renderingThreadId = getCurrentThreadId()
        block()
    } finally {
        renderingThreadId = null
    }
}

fun perform() {
    synchronized(lock) {
        listCopy.addAll(list)
        list.clear()
    }
    listCopy.fastForEach { it.invoke() }
    listCopy.clear()
}

fun onKeyEvent(keyEvent: KeyEvent): Boolean {
    return onPreviewKeyEvent?.invoke(keyEvent) == true ||
        owner.onKeyEvent(keyEvent) ||
        onKeyEvent?.invoke(keyEvent) == true
}

fun onKeyEvent(keyEvent: KeyEvent): Boolean {
    return focusOwner.dispatchKeyEvent(keyEvent) || handleFocusKeys(keyEvent)
}

private fun handleFocusKeys(keyEvent: KeyEvent): Boolean {
    // TODO(b/177931787) : Consider creating a KeyInputManager like we have for FocusManager so
    //  that this common logic can be used by all owners.
    val focusDirection = getFocusDirection(keyEvent)
    if (focusDirection == null || keyEvent.type != KeyEventType.KeyDown) return false

    platformContext.inputModeManager.requestInputMode(InputMode.Keyboard)
    // Consume the key event if we moved focus.
    return focusOwner.moveFocus(focusDirection)
}

private fun getFocusDirection(keyEvent: KeyEvent): FocusDirection? {
    return when (keyEvent.key) {
        Key.Tab -> if (keyEvent.isShiftPressed) FocusDirection.Previous else FocusDirection.Next
        Key.DirectionCenter -> FocusDirection.Enter
        Key.Back -> FocusDirection.Exit
        else -> null
    }
